import { AspectRatio } from "@/components/ui/aspect-ratio"

export function Example() {
  return (
    <div class="w-72">
      <AspectRatio ratio={16 / 9}>
        <img src="/heron.jpg" alt="A heron on one leg" class="h-full w-full object-cover" />
      </AspectRatio>
    </div>
  )
}
